        'all_numbers': all_the_numbers(rolls),
        'ordered_four': ordered_subset_of_four(rolls)
    }

def get_best_game_score(turn1_scores, turn2_scores):
    categories = list(turn1_scores.keys())
    best_score = 0
    for cat1 in categories:
        for cat2 in categories:
            if cat1 != cat2:
                score = turn1_scores[cat1] + turn2_scores[cat2]
                if score > best_score:
                    best_score = score
    return best_score

