    if game_num in game_turns:
        turns = game_turns[game_num]
        if len(turns) == 2:
            game_scores[game_num] = get_best_game_score(turns[0], turns[1])
        elif len(turns) == 1:
            # For incomplete games, use best single category score
            game_scores[game_num] = get_best_single_turn_score(turns[0])
