player1_wins = 0
player2_wins = 0
ties = 0

for i in range(1, 1501):
    odd_game = 2 * i - 1
    even_game = 2 * i

    score1 = game_scores.get(odd_game, 0)
    score2 = game_scores.get(even_game, 0)

    if score1 > score2:
        player1_wins += 1
    elif score2 > score1:
        player2_wins += 1
    else:
        ties += 1

print(f"\nPlayer 1 wins: {player1_wins}")
print(f"Player 2 wins: {player2_wins}")
print(f"Ties: {ties}")
print(f"\nAnswer (P1 wins - P2 wins): {player1_wins - player2_wins}")

with open('/root/answer.txt', 'w') as f:
    f.write(str(player1_wins - player2_wins))

print("\nAnswer written to /root/answer.txt")
EOF
